 */
/* covariance.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stdlib.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop

  /* =================================================================
   * Phase 1: Compute column means.
   *
   * Original iterates column-by-column over data (stride-M access).
   * Optimized to iterate row-by-row (stride-1 access) for much
   * better spatial locality and cache line utilization.
   * ================================================================= */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      mean[j] += data[i][j];
  for (j = 0; j < _PB_M; j++)
    mean[j] /= float_n;

  /* =================================================================
   * Phase 2: Center data by subtracting column means.
   * Already optimal row-major access pattern (same as original).
   * ================================================================= */
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

  /* =================================================================
   * Phase 3: Transpose data (N×M) into data_T (M×N).
   *
   * The original covariance loop accesses data[k][i] and data[k][j]
   * which is column-wise (stride-M). Transposing converts these to
   * sequential row accesses (stride-1), enabling effective hardware
   * prefetching and SIMD auto-vectorization.
   *
   * Uses a tiled transpose: within each 32×32 tile, both source and
   * destination fit in L1 cache, minimizing cache misses.
   * ================================================================= */
  DATA_TYPE *restrict data_T = (DATA_TYPE *)malloc(
      (size_t)_PB_M * (size_t)_PB_N * sizeof(DATA_TYPE));

  {
    #define TRANS_TILE 32
    int ii, jj;
    for (ii = 0; ii < _PB_N; ii += TRANS_TILE) {
      int i_end = ii + TRANS_TILE;
      if (i_end > _PB_N) i_end = _PB_N;
      for (jj = 0; jj < _PB_M; jj += TRANS_TILE) {
        int j_end = jj + TRANS_TILE;
        if (j_end > _PB_M) j_end = _PB_M;
        for (i = ii; i < i_end; i++)
          for (j = jj; j < j_end; j++)
            data_T[(size_t)j * _PB_N + i] = data[i][j];
      }
    }
  }

  /* =================================================================
   * Phase 4: Compute covariance matrix using transposed data.
   *
   * cov[i][j] = dot(data_T_row_i, data_T_row_j) / (n - 1)
   *
   * Both rows are now accessed sequentially (stride-1), which the
   * compiler can auto-vectorize efficiently with SIMD instructions.
   *
   * Register blocking (4-way j-unrolling): for each i, we compute
   * 4 dot products simultaneously. This loads data_T[i][k] once and
   * reuses it for 4 FMA operations, reducing memory traffic for
   * the i-th row by ~4x and increasing instruction-level parallelism
   * with 4 independent accumulator chains.
   * ================================================================= */
  {
    DATA_TYPE inv_fn = SCALAR_VAL(1.0) / (float_n - SCALAR_VAL(1.0));

    for (i = 0; i < _PB_M; i++) {
      const DATA_TYPE *restrict ri = &data_T[(size_t)i * _PB_N];
      j = i;

      /* 4-way unrolled: compute 4 dot products sharing ri loads */
      for (; j + 3 < _PB_M; j += 4) {
        const DATA_TYPE *restrict r0 = &data_T[(size_t)(j  ) * _PB_N];
        const DATA_TYPE *restrict r1 = &data_T[(size_t)(j+1) * _PB_N];
        const DATA_TYPE *restrict r2 = &data_T[(size_t)(j+2) * _PB_N];
        const DATA_TYPE *restrict r3 = &data_T[(size_t)(j+3) * _PB_N];
        DATA_TYPE s0 = SCALAR_VAL(0.0), s1 = SCALAR_VAL(0.0);
        DATA_TYPE s2 = SCALAR_VAL(0.0), s3 = SCALAR_VAL(0.0);

        for (k = 0; k < _PB_N; k++) {
          DATA_TYPE v = ri[k];
          s0 += v * r0[k];
          s1 += v * r1[k];
          s2 += v * r2[k];
          s3 += v * r3[k];
        }

        cov[i][j  ] = s0 * inv_fn; cov[j  ][i] = cov[i][j  ];
        cov[i][j+1] = s1 * inv_fn; cov[j+1][i] = cov[i][j+1];
        cov[i][j+2] = s2 * inv_fn; cov[j+2][i] = cov[i][j+2];
        cov[i][j+3] = s3 * inv_fn; cov[j+3][i] = cov[i][j+3];
      }

      /* Scalar remainder for leftover j values */
      for (; j < _PB_M; j++) {
        const DATA_TYPE *restrict rj = &data_T[(size_t)j * _PB_N];
        DATA_TYPE s = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_N; k++)
          s += ri[k] * rj[k];
        cov[i][j] = s * inv_fn;
        cov[j][i] = cov[i][j];
      }
    }
  }

  free(data_T);

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
