static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /*
   * Tile size for blocking the covariance output in L1 data cache.
   * COV_TILE^2 * sizeof(DATA_TYPE) must fit comfortably in L1D.
   * For double: 32^2 * 8 = 8 KB, well within typical 32 KB L1D,
   * leaving ample room for data row segments (~512 B) and overhead.
   */
  #define COV_TILE 32

#pragma scop

  /* ================================================================
   * Phase 1: Compute column means
   *
   * Optimization: Row-major traversal (i outer, j inner) gives
   * stride-1 access to data[i][j], exploiting spatial locality.
   * The original column-major order (j outer, i inner) caused
   * stride-M accesses, thrashing the cache.
   * ================================================================ */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      mean[j] += data[i][j];

  /* Single division + M multiplications instead of M divisions */
  {
    DATA_TYPE inv_n = SCALAR_VAL(1.0) / float_n;
    for (j = 0; j < _PB_M; j++)
      mean[j] *= inv_n;
  }

  /* ================================================================
   * Phase 2: Center data by subtracting column means
   * Already row-major (i outer, j inner) -- good spatial locality.
   * ================================================================ */
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

  /* ================================================================
   * Phase 3: Compute covariance via tiled outer-product accumulation
   *
   * Original loop nest:
   *   for i: for j>=i: for k: cov[i][j] += data[k][i] * data[k][j]
   *   Inner k-loop accesses data COLUMNS (stride M) -> cache misses.
   *
   * Restructured as tiled outer products:
   *   for each (i,j) output tile [fits in L1]:
   *     for k = 0..N-1:
   *       for i in tile: for j in tile:
   *         cov[i][j] += data[k][i] * data[k][j]
   *
   * Key benefits:
   * (1) Innermost j-loop accesses data[k][j] at stride 1 (row-major),
   *     enabling auto-vectorization and hardware prefetching.
   * (2) The cov tile (8 KB) stays in L1 across all N iterations of k,
   *     providing maximal temporal reuse.
   * (3) data[k][i] is broadcast-multiplied across the j-loop --
   *     a classic BLAS-like DAXPY pattern the compiler vectorizes well.
   * (4) Total main-memory traffic reduced ~COV_TILE-fold vs original.
   * ================================================================ */
  {
    DATA_TYPE inv_nm1 = SCALAR_VAL(1.0) / (float_n - SCALAR_VAL(1.0));
    int pb_m = _PB_M;
    int pb_n = _PB_N;

    /* Iterate over tiles of the upper-triangular covariance matrix */
    for (int ii = 0; ii < pb_m; ii += COV_TILE) {
      int i_end = ii + COV_TILE;
      if (i_end > pb_m) i_end = pb_m;

      for (int jj = ii; jj < pb_m; jj += COV_TILE) {
        int j_end = jj + COV_TILE;
        if (j_end > pb_m) j_end = pb_m;

        /* Zero-initialize this cov tile.
         * For diagonal tiles (ii==jj) we compute the full square block
         * for vectorization efficiency; the lower-triangle portion is
         * harmlessly overwritten in the symmetrize step below. */
        for (i = ii; i < i_end; i++)
          for (j = jj; j < j_end; j++)
            cov[i][j] = SCALAR_VAL(0.0);

        /* Accumulate outer-product (rank-1) contributions from every
         * centered data row.  The j-loop is the auto-vectorizable
         * innermost loop with stride-1 access to cov[i][j] and
         * data[k][j]. */
        for (k = 0; k < pb_n; k++) {
          for (i = ii; i < i_end; i++) {
            DATA_TYPE val_i = data[k][i];
            for (j = jj; j < j_end; j++)
              cov[i][j] += val_i * data[k][j];
          }
        }

        /* Normalize by (n-1) and mirror upper triangle to lower */
        if (ii == jj) {
          /* Diagonal tile: process only upper triangle (j >= i) */
          for (i = ii; i < i_end; i++)
            for (j = i; j < j_end; j++) {
              cov[i][j] *= inv_nm1;
              cov[j][i] = cov[i][j];
            }
        } else {
          /* Off-diagonal tile: all entries satisfy j > i (jj > ii) */
          for (i = ii; i < i_end; i++)
            for (j = jj; j < j_end; j++) {
              cov[i][j] *= inv_nm1;
              cov[j][i] = cov[i][j];
            }
        }
      }
    }
  }

#pragma endscop

}


