   1) Row-major mean computation for stride-1 spatial locality
   2) Tiled outer-product covariance keeping cov tile in L1
   3) Diagonal vs off-diagonal tile split for SIMD-friendly loops
   4) Division strength reduction (precomputed reciprocals)
   5) AVX2+FMA target for 4-wide double SIMD with fused multiply-add
*/
#pragma GCC push_options
#pragma GCC target("avx2,fma")
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop

  /* ================================================================
   * Phase 1: Compute column means via row-major traversal.
   *
   * Original: for each column j, iterate rows i → data[i][j] is
   * stride-M (one cache miss per access in a row-major layout).
   * Optimized: for each row i, sweep columns j → stride-1 access,
   * accumulating all M column sums simultaneously.
   * ================================================================ */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      mean[j] += data[i][j];

  /* Strength reduction: 1 division + M multiplications
   * replaces M divisions. */
  {
    DATA_TYPE inv_n = SCALAR_VAL(1.0) / float_n;
    for (j = 0; j < _PB_M; j++)
      mean[j] *= inv_n;
  }

  /* ================================================================
   * Phase 2: Center data by subtracting column means.
   * Already row-major — no restructuring needed.
   * ================================================================ */
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

  /* ================================================================
   * Phase 3: Compute upper-triangular covariance matrix.
   *
   *   cov[i][j] = (1/(n-1)) * sum_k data[k][i] * data[k][j]
   *
   * OPTIMIZATION: Tiled outer-product accumulation.
   *
   * Original inner k-loop accesses data[k][i] with stride M (column
   * access) causing severe cache thrashing: ~M^2*N L1 misses total.
   *
   * Restructured: tile the (i,j) output space into TILE x TILE blocks.
   * For each tile, sweep all data rows k using the outer-product form:
   *   for k: cov_tile += data[k][tile_i_range] (x) data[k][tile_j_range]
   *
   * Key benefits:
   * (a) data[k][*] is accessed stride-1 within each row (row-major).
   * (b) The cov tile (TILE*TILE*8 = 8 KB) stays resident in L1 cache
   *     while streaming through all N data rows.
   * (c) Off-diagonal tiles have fixed rectangular inner loops enabling
   *     full auto-vectorization (AVX2: 4 doubles/vector).
   * (d) Diagonal tiles (~5% of work) handle the triangular j>=i shape.
   * ================================================================ */

  /* Tile size 32: 32*32*8 = 8 KB fits well in L1 (32-48 KB),
   * leaving room for data row strips (~512 B per k iteration).
   * Inner j-loop of 32 iters = 8 AVX2 vector iterations. */
  #define TILE 32

  /* Zero the full matrix (IEEE 754 double 0.0 is all-zero bits) */
  for (i = 0; i < _PB_M; i++)
    for (j = 0; j < _PB_M; j++)
      cov[i][j] = SCALAR_VAL(0.0);

  /* --- Tiled outer-product accumulation (upper triangle) --- */
  for (int ii = 0; ii < _PB_M; ii += TILE) {
    int ie = ii + TILE;
    if (ie > _PB_M) ie = _PB_M;

    /* Diagonal tile (jj == ii): triangular inner j-loop (j >= i). */
    for (k = 0; k < _PB_N; k++) {
      for (i = ii; i < ie; i++) {
        DATA_TYPE d_ki = data[k][i]; /* hoisted out of j-loop */
        for (j = i; j < ie; j++)
          cov[i][j] += d_ki * data[k][j];
      }
    }

    /* Off-diagonal tiles (jj > ii): rectangular j-loop with
     * bounds independent of i — ideal for auto-vectorization. */
    for (int jj = ii + TILE; jj < _PB_M; jj += TILE) {
      int je = jj + TILE;
      if (je > _PB_M) je = _PB_M;

      for (k = 0; k < _PB_N; k++) {
        for (i = ii; i < ie; i++) {
          DATA_TYPE d_ki = data[k][i];
          for (j = jj; j < je; j++)
            cov[i][j] += d_ki * data[k][j];
        }
      }
    }
  }

  /* Scale by 1/(n-1) and mirror to lower triangle.
   * Strength reduction: 1 division + ~M^2/2 multiplications. */
  {
    DATA_TYPE inv_fn1 = SCALAR_VAL(1.0) / (float_n - SCALAR_VAL(1.0));
    for (i = 0; i < _PB_M; i++) {
      cov[i][i] *= inv_fn1;
      for (j = i + 1; j < _PB_M; j++) {
        cov[i][j] *= inv_fn1;
        cov[j][i] = cov[i][j];
      }
    }
  }

  #undef TILE

#pragma endscop
}
